// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 extraDeposit) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(extraDeposit > 0);
        // Make sure total deposits don't exceed balance constraints
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(extraDeposit <= type(uint256).max / 2);
        uint256 total = depositAmount + extraDeposit;
        vm.assume(total >= depositAmount); // overflow check
        vm.deal(actor, total);

        vm.prank(actor);
        c.deposit{value: depositAmount}();
        vm.prank(actor);
        c.deposit{value: extraDeposit}();

        // withdrawAll draws the actor's entire credit
        vm.prank(actor);
        c.withdrawAll();

        // After withdrawAll, the remaining balance must equal total deposited minus what actor withdrew.
        // Since actor withdrew all its credit, balance should still equal the unchanged deposits from others.
        // But there are no other depositors here, so balance should be exactly 0.
        // The invariant: total deposited = total withdrawn + contract balance.
        // Since actor is the only depositor and withdrew its full credit, balance must be 0.
        assertTrue(address(c).balance == 0);
    }
}

