pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= 100 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= 100 ether);
        address alice = makeAddr("alice");
        vm.deal(alice, 200 ether);
        vm.prank(alice);
        c.deposit{value: depositAmount}();
        uint256 deposited = depositAmount;
        uint256 withdrawn = 0;
        vm.prank(alice);
        try c.withdrawAll() {
            withdrawn = withdrawAmount;
        } catch {
            withdrawn = 0;
        }
        uint256 contractBalance = address(c).balance;
        assertTrue(contractBalance + withdrawn >= deposited);
    }
}

