pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 totalDeposited;
    uint256 totalWithdrawn;

    function setUp() public {
        c = new C();
        totalDeposited = 0;
        totalWithdrawn = 0;
    }

    function testFuzz_property(uint256 depositA, uint256 depositB, uint256 depositC, bool withdrawA, bool withdrawB) public {
        // Bound deposits to avoid overflow and ensure enough balance
        depositA = bound(depositA, 0, 1 ether);
        depositB = bound(depositB, 0, 1 ether);
        depositC = bound(depositC, 0, 1 ether);

        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(alice, depositA);
        vm.prank(alice);
        c.deposit{value: depositA}();
        totalDeposited += depositA;

        vm.deal(bob, depositB);
        vm.prank(bob);
        c.deposit{value: depositB}();
        totalDeposited += depositB;

        vm.deal(alice, depositC);
        vm.prank(alice);
        c.deposit{value: depositC}();
        totalDeposited += depositC;

        if (withdrawA) {
            uint256 creditBefore = c.credit(alice);
            vm.prank(alice);
            c.withdrawAll();
            totalWithdrawn += creditBefore;
        }

        if (withdrawB) {
            uint256 creditBefore = c.credit(bob);
            vm.prank(bob);
            c.withdrawAll();
            totalWithdrawn += creditBefore;
        }

        assertEq(c.balance(), totalDeposited - totalWithdrawn, "Balance invariant violated");
    }
}

