        vm.assume(amount > 0);
        address actor = address(0x1000);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // Record pre-state
        uint256 preCredit = c.credit(actor);
        uint256 preBalance = address(c).balance;

        vm.prank(actor);
        bool withdrawOk;
        try c.withdrawAll() { withdrawOk = true; } catch { withdrawOk = false; }

