        // 0 value (e.g., 0x02 rejects value).
        // This should work.
        // However, the test runs with the fuzzer generating addresses. It might not
        // generate a precompile that rejects 0 value within 256 runs? Precompiles
        // 0x01 to 0x09: 0x01 (ecRecover) accepts 0 value, 0x02 (SHA256) rejects value,
        // 0x03 (RIPEMD160) accepts 0? Actually, RIPEMD160 rejects value? I think
        // 0x03 also rejects value. Most precompiles reject value except ecRecover.
        // So if we restrict to low addresses, the fuzzer will likely pick one that
        // rejects value. Let's use `vm.assume(uint160(caller) <= 0xff)`.
        // That gives 256 addresses. The fuzzer will try them.
        // The reference never reverts; the mutant reverts on many of them.
        // This property is: "withdrawAll should never revert".
        // The reference satisfies it; the mutant breaks it.
        // Let's implement.

        vm.assume(caller != address(0));
        // Ensure caller is a contract (precompile) that might reject 0-value transfers.
        vm.assume(caller.codehash != bytes32(0));
        vm.assume(uint160(caller) <= 0xff); // restrict to low addresses (precompiles)

        // Ensure caller has zero credit initially.
        uint256 creditBeforeCall = c.credit(caller);
        // No deposit, so credit is 0.

        // The caller must have no ETH to send? Not needed.
        // Call withdrawAll as the caller, catch revert.
        bool success;
        vm.prank(caller);
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }

